struct PinManager {
  static bool allocateMultiplePins(const managed_pin_type* pins, size_t count, PinOwner) {
    for (size_t i = 0; i < count; i++) {
      if (pins[i].pin < 0 || pins[i].pin >= 64 || cinemaTest::ownedPins[pins[i].pin] || pins[i].pin == cinemaTest::conflictPin) return false;
    }
    for (size_t i = 0; i < count; i++) cinemaTest::ownedPins[pins[i].pin] = true;
    return true;
  }
  static void deallocateMultiplePins(const managed_pin_type* pins, size_t count, PinOwner) {
    for (size_t i = 0; i < count; i++) {
      assert(cinemaTest::ownedPins[pins[i].pin]);
      cinemaTest::ownedPins[pins[i].pin] = false;
    }
  }
};
inline void* heap_caps_malloc(size_t size, int) {
  if (++cinemaTest::allocationCalls == cinemaTest::failAllocation) return nullptr;
  cinemaTest::liveAllocations++;
  return malloc(size);
}
inline void heap_caps_free(void* buffer) { cinemaTest::liveAllocations--; free(buffer); }
