inline void esp_rom_gpio_connect_in_signal(int pin, int signal, bool invert) {
  assert(cinemaTest::busActive && signal == spi_periph_signal[SPI2_HOST].spiq_in && !invert);
  assert(cinemaTest::pinModes.at(pin) == GPIO_MODE_INPUT);
  cinemaTest::selectedMiso = pin;
}
inline esp_err_t spi_bus_initialize(int host, const spi_bus_config_t* config, int dma) {
  assert(host == SPI2_HOST && dma == SPI_DMA_CH_AUTO && !cinemaTest::busActive);
  cinemaTest::busActive = true;
  cinemaTest::matrixFlags = config->flags;
  if (cinemaTest::onBusInitialize) cinemaTest::onBusInitialize();
  return ESP_OK;
}
inline esp_err_t spi_bus_free(int) { cinemaTest::busActive = false; return ESP_OK; }
inline esp_err_t spi_bus_add_device(int, const spi_device_interface_config_t* config, spi_device_handle_t* handle) {
  for (auto& device : cinemaTest::devices) {
    if (device.active) continue;
    device.cs = config->spics_io_num;
    device.active = true;
    *handle = &device;
    return ESP_OK;
  }
  return ESP_FAIL;
}
inline esp_err_t spi_bus_remove_device(spi_device_handle_t handle) { handle->active = false; return ESP_OK; }
// Each simulated camera drives a distinct return wire regardless of the other camera's CS.
inline esp_err_t spi_device_transmit(spi_device_handle_t handle, spi_transaction_t* transaction) {
  using namespace cinema;
  assert(handle->active && transaction->length == spi::SLOT_SIZE * 8 && transaction->rxlength == transaction->length);
  const bool left = handle->cs == 5;
  assert(cinemaTest::selectedMiso == (left ? 19 : 21));
  cinemaTest::returnPins.push_back(cinemaTest::selectedMiso);
  spi::SlotView request;
  assert(spi::decodeSlot(static_cast<const uint8_t*>(transaction->tx_buffer), spi::SLOT_SIZE, &request) == spi::SlotStatus::Empty);
  protocol::PacketHeader heartbeat;
  heartbeat.type = protocol::MessageType::Heartbeat;
  heartbeat.source = left ? protocol::NodeRole::CameraLeft : protocol::NodeRole::CameraRight;
  heartbeat.target = protocol::NodeRole::Controller;
  heartbeat.bootId = left ? 42 : 43;
  heartbeat.sequence = ++cinemaTest::sequence;
  uint8_t packet[protocol::PACKET_HEADER_SIZE + protocol::PACKET_CRC_SIZE];
  size_t packetSize = 0;
  assert(protocol::encodePacket(heartbeat, nullptr, 0, packet, sizeof(packet), &packetSize) == protocol::PacketStatus::Ok);
  auto output = static_cast<uint8_t*>(transaction->rx_buffer);
  assert(spi::encodeSlot(packet, packetSize, 0, heartbeat.sequence, output, spi::SLOT_SIZE) == spi::SlotStatus::Ok);
  if (cinemaTest::corruptSlot) { output[12] ^= 1; cinemaTest::corruptSlot = false; }
  return ESP_OK;
}
